{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "pomodoro_intro_section",
        "applying_pomodoro_section",
        "benefits_section",
        "research_paper_section",
        "quick_actions_section"
      ]
    },
    "pomodoro_intro_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "pomodoro_intro_header",
        "pomodoro_intro_text"
      ]
    },
    "pomodoro_intro_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "pomodoro_intro_icon",
        "pomodoro_intro_title"
      ]
    },
    "pomodoro_intro_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000651_01_1_clock.svg"
      },
      "children": []
    },
    "pomodoro_intro_title": {
      "type": "Text",
      "props": {
        "text": "Pomodoro Technique: Focused Work Intervals",
        "variant": "h2"
      },
      "children": []
    },
    "pomodoro_intro_text": {
      "type": "Text",
      "props": {
        "text": "The Pomodoro Technique is a time management method developed by Francesco Cirillo in the late 1980s. It uses a timer to break down work into focused intervals, traditionally 25 minutes in length, separated by short breaks. Each interval is known as a \"pomodoro,\" named after the tomato-shaped kitchen timer Cirillo used."
      },
      "children": []
    },
    "applying_pomodoro_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "applying_pomodoro_header",
        "applying_pomodoro_list"
      ]
    },
    "applying_pomodoro_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "applying_pomodoro_icon",
        "applying_pomodoro_title"
      ]
    },
    "applying_pomodoro_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000651_01_2_check-circle.svg"
      },
      "children": []
    },
    "applying_pomodoro_title": {
      "type": "Text",
      "props": {
        "text": "Applying the Pomodoro Technique: Step-by-Step",
        "variant": "h2"
      },
      "children": []
    },
    "applying_pomodoro_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "applying_pomodoro_item_1",
        "applying_pomodoro_item_2",
        "applying_pomodoro_item_3",
        "applying_pomodoro_item_4",
        "applying_pomodoro_item_5"
      ]
    },
    "applying_pomodoro_item_1": {
      "type": "Text",
      "props": {
        "text": "1. Choose a Task: Select a specific task you need to complete."
      },
      "children": []
    },
    "applying_pomodoro_item_2": {
      "type": "Text",
      "props": {
        "text": "2. Set the Timer: Set your timer for 25 minutes (one pomodoro)."
      },
      "children": []
    },
    "applying_pomodoro_item_3": {
      "type": "Text",
      "props": {
        "text": "3. Work with Focus: Work on the chosen task intently until the timer rings. Avoid distractions; if a thought or task unrelated to your current work arises, quickly jot it down and return to your task."
      },
      "children": []
    },
    "applying_pomodoro_item_4": {
      "type": "Text",
      "props": {
        "text": "4. Take a Short Break: When the timer rings, stop working immediately. Take a short break of 3-5 minutes. Use this time to relax, stretch, or grab a drink."
      },
      "children": []
    },
    "applying_pomodoro_item_5": {
      "type": "Text",
      "props": {
        "text": "5. Repeat and Long Break: After every four pomodoros, take a longer break of 15-30 minutes. This helps prevent burnout and allows for deeper mental rest. After the long break, reset your pomodoro count and start again."
      },
      "children": []
    },
    "benefits_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "benefits_header",
        "benefits_list"
      ]
    },
    "benefits_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "benefits_icon",
        "benefits_title"
      ]
    },
    "benefits_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000651_01_3_lightbulb.svg"
      },
      "children": []
    },
    "benefits_title": {
      "type": "Text",
      "props": {
        "text": "Benefits of the Pomodoro Technique",
        "variant": "h2"
      },
      "children": []
    },
    "benefits_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "benefit_1",
        "benefit_2",
        "benefit_3",
        "benefit_4",
        "benefit_5",
        "benefit_6"
      ]
    },
    "benefit_1": {
      "type": "Text",
      "props": {
        "text": "• Improved Focus and Concentration: Trains your brain to stay focused for defined periods, reducing mind-wandering."
      },
      "children": []
    },
    "benefit_2": {
      "type": "Text",
      "props": {
        "text": "• Reduced Burnout: Regular, scheduled breaks help prevent mental fatigue and maintain energy levels."
      },
      "children": []
    },
    "benefit_3": {
      "type": "Text",
      "props": {
        "text": "• Enhanced Productivity: Encourages you to start and complete tasks by breaking them into manageable chunks."
      },
      "children": []
    },
    "benefit_4": {
      "type": "Text",
      "props": {
        "text": "• Better Time Estimation: By tracking how many pomodoros a task takes, you gain a more accurate sense of your work pace."
      },
      "children": []
    },
    "benefit_5": {
      "type": "Text",
      "props": {
        "text": "• Increased Motivation: Each completed pomodoro provides a sense of accomplishment, fostering momentum."
      },
      "children": []
    },
    "benefit_6": {
      "type": "Text",
      "props": {
        "text": "• Reduced Distractions: The commitment to focus during a pomodoro helps you defer interruptions and manage urges to multitask."
      },
      "children": []
    },
    "research_paper_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "research_paper_header",
        "research_paper_intro_text",
        "research_paper_breakdown_text",
        "research_paper_breakdown_list",
        "research_paper_task_types_text",
        "research_paper_task_types_list",
        "research_paper_distractions_text",
        "research_paper_progress_text"
      ]
    },
    "research_paper_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "research_paper_icon",
        "research_paper_title"
      ]
    },
    "research_paper_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000651_01_4_journal-text.svg"
      },
      "children": []
    },
    "research_paper_title": {
      "type": "Text",
      "props": {
        "text": "Applying Pomodoro to Research Paper Writing",
        "variant": "h2"
      },
      "children": []
    },
    "research_paper_intro_text": {
      "type": "Text",
      "props": {
        "text": "Writing a research paper can feel overwhelming, but the Pomodoro Technique can make it more manageable:"
      },
      "children": []
    },
    "research_paper_breakdown_text": {
      "type": "Text",
      "props": {
        "text": "• Break Down the Project: Instead of thinking \"write the paper,\" define very specific, small tasks for each pomodoro. Examples include:"
      },
      "children": []
    },
    "research_paper_breakdown_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs",
        "paddingHorizontal": 16
      },
      "children": [
        "breakdown_item_1",
        "breakdown_item_2",
        "breakdown_item_3",
        "breakdown_item_4",
        "breakdown_item_5",
        "breakdown_item_6"
      ]
    },
    "breakdown_item_1": {
      "type": "Text",
      "props": {
        "text": "• \"Find 3 more sources for the literature review.\""
      },
      "children": []
    },
    "breakdown_item_2": {
      "type": "Text",
      "props": {
        "text": "• \"Read and annotate one article.\""
      },
      "children": []
    },
    "breakdown_item_3": {
      "type": "Text",
      "props": {
        "text": "• \"Outline section 2, 'Methodology'.\""
      },
      "children": []
    },
    "breakdown_item_4": {
      "type": "Text",
      "props": {
        "text": "• \"Write the introduction for section 1.\""
      },
      "children": []
    },
    "breakdown_item_5": {
      "type": "Text",
      "props": {
        "text": "• \"Edit the conclusion paragraph.\""
      },
      "children": []
    },
    "breakdown_item_6": {
      "type": "Text",
      "props": {
        "text": "• \"Format references for 5 sources.\""
      },
      "children": []
    },
    "research_paper_task_types_text": {
      "type": "Text",
      "props": {
        "text": "• Categorize your tasks into 'writing,' 'research,' and 'editing' to ensure a balanced approach."
      },
      "children": []
    },
    "research_paper_task_types_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs",
        "paddingHorizontal": 16
      },
      "children": [
        "task_type_item_1",
        "task_type_item_2",
        "task_type_item_3"
      ]
    },
    "task_type_item_1": {
      "type": "Text",
      "props": {
        "text": "• Writing: Drafting new content, outlining."
      },
      "children": []
    },
    "task_type_item_2": {
      "type": "Text",
      "props": {
        "text": "• Research: Finding sources, reading, annotating."
      },
      "children": []
    },
    "task_type_item_3": {
      "type": "Text",
      "props": {
        "text": "• Editing: Proofreading, revising, formatting."
      },
      "children": []
    },
    "research_paper_distractions_text": {
      "type": "Text",
      "props": {
        "text": "• Minimize Distractions: During your 25-minute pomodoro, turn off notifications, close unnecessary tabs, and focus solely on the task at hand. Use the short breaks to check emails or messages if absolutely necessary."
      },
      "children": []
    },
    "research_paper_progress_text": {
      "type": "Text",
      "props": {
        "text": "• Track Your Progress: Keep a simple log of completed pomodoros. This visual representation of your work can be highly motivating and help you refine your time estimates for future tasks."
      },
      "children": []
    },
    "quick_actions_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "quick_actions_header",
        "quick_actions_button_stack"
      ]
    },
    "quick_actions_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "quick_actions_icon",
        "quick_actions_title"
      ]
    },
    "quick_actions_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000651_01_5_lightning.svg"
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_button_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "justify": "center"
      },
      "children": [
        "start_timer_button",
        "learn_more_button"
      ]
    },
    "start_timer_button": {
      "type": "Button",
      "props": {
        "label": "Start Pomodoro Timer",
        "variant": "primary"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.google.com/search?q=pomodoro+timer"
          }
        }
      }
    },
    "learn_more_button": {
      "type": "Button",
      "props": {
        "label": "Learn More",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://en.wikipedia.org/wiki/Pomodoro_Technique"
          }
        }
      }
    }
  }
}
